// =====================================================================
// FACTORY CONFIG - ศูนย์รวมค่าตั้งค่าของโรงงานทั้งหมด
//
// วิธีแก้ค่า (เลือกอย่างใดอย่างหนึ่ง):
//   1. แก้ตัวเลข/ข้อความใน DEFAULTS ข้างล่างนี้ตรง ๆ (ง่ายสุด ใช้ได้ทุกแพลน)
//   2. หรือตั้งใน n8n Variables (Settings > Variables) ชื่อเดียวกัน - จะทับ DEFAULTS
//   3. หรือตั้ง environment variable (เฉพาะ self-hosted) - จะทับ DEFAULTS เช่นกัน
//
// แก้ที่ workflow 01 ตัวเดียวพอ: sub-workflow ทุกตัวรับ cfg ต่อจากแม่อัตโนมัติ
// =====================================================================
const DEFAULTS = {
  "OPENAI_MODEL_TEXT": "gpt-4.1",
  "GEMINI_API_BASE": "https://generativelanguage.googleapis.com",
  "GEMINI_MODEL_TEXT": "gemini-flash-latest",
  "OPENAI_MODEL_IMAGE": "gpt-image-1",
  "OPENAI_IMAGE_QUALITY": "high",
  "IMAGE_QUALITY_COVER": "high",
  "IMAGE_QUALITY_PAGE": "medium",
  "IMAGE_QUALITY_SMALL": "low",
  "GENERATE_SEPARATE_PREVIEWS": "false",
  "PROMPT_VERSION": "v1.0.0",
  "ETSY_API_BASE": "https://openapi.etsy.com",
  "ETSY_API_KEY": "",
  "ETSY_SHOP_ID": "",
  "ETSY_LISTING_STATE": "draft",
  "ETSY_TAXONOMY_ID": 2078,
  "GDRIVE_ROOT_FOLDER_ID": "root",
  "DB_TYPE": "postgres",
  "DB_SQLITE_PATH": "/home/node/.n8n/adpf.db",
  "FACTORY_ROTATION": "planner,printable,canva,wallart,resume,spreadsheet,kids,svg",
  "ALERT_WEBHOOK_URL": "",
  "IDEA_TARGET_COUNT": 200,
  "IDEA_BATCH_SIZE": 25,
  "DUPLICATE_SIMILARITY_THRESHOLD": 0.62,
  "ALLOW_PRODUCT_REVISION": "false",
  "BUDGET_DAILY_USD": 20,
  "BUDGET_MONTHLY_USD": 300,
  "BUDGET_RUN_RESERVE_USD": 3,
  "OPENAI_IMAGE_UNIT_COST_USD": 0.19,
  "OPENAI_CHAT_RUN_COST_USD": 0.12,
  "OPENAI_PRICE_OVERRIDE_JSON": "{}",
  "LEARNING_WINDOW_DAYS": 30,
  "LEARNING_MIN_SAMPLE": 15,
  "AB_MIN_VIEWS_PER_ARM": 200,
  "AB_MIN_RELATIVE_LIFT": 0.2
};

const first = $input.first();
const incoming = first && first.json ? first.json : {};
const parentCfg = incoming.cfg && typeof incoming.cfg === 'object' ? incoming.cfg : {};

// ทั้ง $vars และ $env อาจไม่มีอยู่เลย (n8n Cloud) - แตะผ่าน try เท่านั้น
const readVars = (key) => {
  try {
    if (typeof $vars !== 'undefined' && $vars[key] !== undefined && $vars[key] !== '') {
      return $vars[key];
    }
  } catch (e) { /* Variables not available on this plan */ }
  return undefined;
};
const readEnv = (key) => {
  try {
    if (typeof $env !== 'undefined' && $env[key] !== undefined && $env[key] !== '') {
      return $env[key];
    }
  } catch (e) { /* env access blocked or not present */ }
  return undefined;
};

const cfg = {};
const sources = {};
for (const key of Object.keys(DEFAULTS)) {
  if (parentCfg[key] !== undefined) { cfg[key] = parentCfg[key]; sources[key] = 'parent'; continue; }
  const fromVars = readVars(key);
  if (fromVars !== undefined) { cfg[key] = fromVars; sources[key] = 'variables'; continue; }
  const fromEnv = readEnv(key);
  if (fromEnv !== undefined) { cfg[key] = fromEnv; sources[key] = 'env'; continue; }
  cfg[key] = DEFAULTS[key]; sources[key] = 'default';
}

return $input.all().map((item) => ({
  json: { ...item.json, cfg, cfg_sources: sources },
  binary: item.binary,
}));

// STEP 1+2 - can this instance resolve its configuration?
// Works on n8n Cloud and self-hosted alike: settings come from the Factory
// Config node (parent cfg > Variables > env > built-in defaults), so nothing
// here depends on environment variables existing.
const item = $input.first().json;
const cfg = item.cfg || {};
const sources = item.cfg_sources || {};

const cfgReady = Object.keys(cfg).length > 0;

const GROUPS = {
  'OpenAI (needed to generate anything)': ['OPENAI_MODEL_TEXT', 'OPENAI_MODEL_IMAGE'],
  'Etsy (needed only to publish)': ['ETSY_API_BASE', 'ETSY_API_KEY', 'ETSY_SHOP_ID'],
  'Google Drive (needed only to back up)': ['GDRIVE_ROOT_FOLDER_ID'],
  'Database (needed for workflows 06-10)': ['DB_TYPE'],
  'Factory settings': ['PROMPT_VERSION', 'FACTORY_ROTATION'],
};

const report = {};
for (const [group, keys] of Object.entries(GROUPS)) {
  report[group] = keys.map((key) => {
    const value = cfg[key];
    const isSet = value !== undefined && value !== null && String(value).trim() !== '';
    return {
      key,
      set: isSet,
      source: sources[key] || 'default',
      value: key.includes('KEY') || key.includes('SECRET')
        ? (isSet ? '(set, hidden)' : null)
        : (isSet ? String(value) : null),
    };
  });
}

const blockers = [];
if (!cfgReady) {
  blockers.push('Factory Config produced no settings - is the node connected before this one?');
}

return [{
  json: {
    step: 'check-setup',
    cfg_ready: cfgReady,
    env_report: report,
    blockers,
    // Flip to false to test the PDF engine without spending anything on OpenAI.
    test_openai: item.test_openai !== false && blockers.length === 0,
    product_title: item.product_title || 'My First Test Product',
    checked_at: new Date().toISOString(),
  },
}];

// STEP 2 - the smallest possible real request. A few hundred tokens, so a
// mistyped API key costs a fraction of a cent to discover.
const ctx = $input.first().json;

return [{
  json: {
    ...ctx,
    system_prompt:
      'You are a setup test. Reply with valid JSON only, nothing else.',
    user_prompt:
      'Write one short marketing line for a printable product called "' +
      ctx.product_title + '". ' +
      'Answer exactly: {"tagline": "...", "three_words": ["...","...","..."]}',
  },
}];

// One reader for both providers. OpenAI answers with choices[].message.content,
// Gemini with candidates[].content.parts[].text - and a build can target either,
// so every parser in this repo would otherwise need two code paths.
const agentContent = (response) => {
  const openai = response && response.choices && response.choices[0]
    && response.choices[0].message;
  if (openai && typeof openai.content === 'string') return openai.content;
  if (openai && openai.refusal) return '';
  const gemini = response && response.candidates && response.candidates[0];
  if (gemini && gemini.content && Array.isArray(gemini.content.parts)) {
    return gemini.content.parts.map((p) => p && p.text).filter(Boolean).join('');
  }
  return '';
};

// Token counts, normalised to the OpenAI field names the cost tracker records.
const agentUsage = (response) => {
  if (response && response.usage) return response.usage;
  const m = response && response.usageMetadata;
  if (!m) return null;
  return {
    prompt_tokens: m.promptTokenCount || 0,
    completion_tokens: m.candidatesTokenCount || 0,
    total_tokens: m.totalTokenCount || 0,
  };
};

// finish_reason / finishReason, same idea.
const agentFinish = (response) => {
  const openai = response && response.choices && response.choices[0];
  if (openai && openai.finish_reason) return openai.finish_reason;
  const gemini = response && response.candidates && response.candidates[0];
  if (gemini && gemini.finishReason) return String(gemini.finishReason).toLowerCase();
  return 'unknown';
};// STEP 3 - did OpenAI answer, and is the answer parseable JSON?
// Both halves matter: a working key that returns prose would break every
// downstream workflow, so the parse is part of the test.
const ctx = $('Build Test Prompt').first().json;
const response = $input.first().json;

const problems = [];
let parsed = null;

const content = agentContent(response);
if (response?.error) {
  problems.push(`OpenAI error: ${response.error.message || JSON.stringify(response.error)}`);
} else if (!content) {
  problems.push('OpenAI returned no content - check the credential and your account credit');
} else {
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    problems.push(`OpenAI replied but not with JSON: ${e.message}`);
  }
}

const usage = response?.usage || {};
// Rough cost at gpt-4.1 list price, just so the number is not a mystery.
const costUsd = ((usage.prompt_tokens || 0) / 1e6) * 2
  + ((usage.completion_tokens || 0) / 1e6) * 8;

return [{
  json: {
    ...ctx,
    openai_ok: problems.length === 0,
    openai_problems: problems,
    openai_reply: parsed,
    openai_usage: {
      prompt_tokens: usage.prompt_tokens || 0,
      completion_tokens: usage.completion_tokens || 0,
      approx_cost_usd: Math.round(costUsd * 1e6) / 1e6,
    },
  },
}];

// OpenAI was skipped on purpose - carry on to the PDF test.
const ctx = $input.first().json;
return [{
  json: {
    ...ctx,
    openai_ok: null,
    openai_problems: [],
    openai_reply: null,
    openai_skipped: true,
    skip_reason: ctx.blockers.length
      ? 'blocked: ' + ctx.blockers.join('; ')
      : 'test_openai was set to false',
  },
}];

// ---------------------------------------------------------------------------
// Minimal PDF 1.4 writer (no external dependencies).
// ---------------------------------------------------------------------------
const PDF_FONT = { regular: 'F1', bold: 'F2' };

// Strip anything Helvetica/WinAnsi cannot show, then escape PDF string syntax.
function pdfEscape(text) {
  return String(text === undefined || text === null ? '' : text)
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[–—]/g, '-')
    .replace(/…/g, '...')
    .replace(/[^\x20-\x7E\xA1-\xFF]/g, '')
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)');
}

// Read width/height/components out of a JPEG SOF marker.
function jpegInfo(buffer) {
  let i = 2;
  while (i < buffer.length - 9) {
    if (buffer[i] !== 0xff) { i += 1; continue; }
    const marker = buffer[i + 1];
    if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
      i += 2;
      continue;
    }
    const length = buffer.readUInt16BE(i + 2);
    const isSOF = marker >= 0xc0 && marker <= 0xcf &&
      marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc;
    if (isSOF) {
      return {
        height: buffer.readUInt16BE(i + 5),
        width: buffer.readUInt16BE(i + 7),
        components: buffer[i + 9],
      };
    }
    i += 2 + length;
  }
  return { width: 1024, height: 1024, components: 3 };
}

// Greedy word wrap. Helvetica averages ~0.5em per character, which is accurate
// enough for body copy at 10-12pt.
function wrapText(text, fontSize, usableWidth) {
  const maxChars = Math.max(20, Math.floor(usableWidth / (fontSize * 0.5)));
  const out = [];
  for (const rawLine of String(text).split('\n')) {
    let line = '';
    for (const word of rawLine.split(/\s+/)) {
      if (!word) continue;
      if (!line.length) { line = word; continue; }
      if ((line + ' ' + word).length <= maxChars) { line += ' ' + word; }
      else { out.push(line); line = word; }
    }
    out.push(line);
  }
  return out;
}

function buildPdf(spec) {
  const PW = spec.width || 595.28;   // A4 portrait by default
  const PH = spec.height || 841.89;
  const margin = spec.margin || 56;
  const bodySize = spec.body_size || 11;
  const leading = Math.round(bodySize * 1.5);
  const usableWidth = PW - margin * 2;

  // Object ids 1-5 are reserved: catalog, page tree, 2 fonts, document info.
  const objects = [null, null, null, null, null];
  const push = (content) => { objects.push(content); return objects.length; };
  const pageIds = [];

  const addPage = (contentStream, extraResources) => {
    const contentId = push(
      `<< /Length ${Buffer.byteLength(contentStream, 'latin1')} >>\n` +
      `stream\n${contentStream}\nendstream`
    );
    const resources =
      `/Font << /F1 3 0 R /F2 4 0 R >>` + (extraResources ? ' ' + extraResources : '');
    pageIds.push(push(
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PW.toFixed(2)} ${PH.toFixed(2)}]` +
      ` /Resources << ${resources} >> /Contents ${contentId} 0 R >>`
    ));
  };

  const footer = (label) => {
    if (!label) return '';
    return `BT /${PDF_FONT.regular} 8 Tf 0.45 0.45 0.45 rg ` +
      `${margin} ${(margin / 2).toFixed(2)} Td (${pdfEscape(label)}) Tj ET 0 0 0 rg\n`;
  };

  for (const page of spec.pages || []) {
    // ---- image page: fit the JPEG inside the page, centred -----------------
    if (page.type === 'image' && page.jpeg_base64) {
      const data = Buffer.from(page.jpeg_base64, 'base64');
      const info = jpegInfo(data);
      const bleed = page.full_bleed ? 0 : margin / 2;
      const scale = Math.min(
        (PW - bleed * 2) / info.width,
        (PH - bleed * 2) / info.height
      );
      const w = info.width * scale;
      const h = info.height * scale;
      const x = (PW - w) / 2;
      const y = (PH - h) / 2;
      const imageId = push(Buffer.concat([
        Buffer.from(
          `<< /Type /XObject /Subtype /Image /Width ${info.width} /Height ${info.height}` +
          ` /ColorSpace ${info.components === 1 ? '/DeviceGray' : '/DeviceRGB'}` +
          ` /BitsPerComponent 8 /Filter /DCTDecode /Length ${data.length} >>\nstream\n`,
          'latin1'
        ),
        data,
        Buffer.from('\nendstream', 'latin1'),
      ]));
      let stream = `q ${w.toFixed(2)} 0 0 ${h.toFixed(2)} ${x.toFixed(2)} ${y.toFixed(2)} cm /Im0 Do Q\n`;
      if (page.caption) {
        stream += `BT /${PDF_FONT.regular} 10 Tf ${margin} ${(y - 18).toFixed(2)} Td ` +
          `(${pdfEscape(page.caption)}) Tj ET\n`;
      }
      stream += footer(page.footer);
      addPage(stream, `/XObject << /Im0 ${imageId} 0 R >>`);
      continue;
    }

    // ---- text page: wrap, then break into as many pages as needed ---------
    const titleSize = page.title_size || (page.cover ? 30 : 18);
    const lines = [];
    // A page whose lines arrived as a single string still typesets.
    const pageLines = Array.isArray(page.lines) ? page.lines
      : (page.lines ? [String(page.lines)] : []);
    for (const raw of pageLines) {
      for (const wrapped of wrapText(raw, bodySize, usableWidth)) lines.push(wrapped);
    }

    const firstTop = PH - margin - (page.title ? titleSize + 22 : 0);
    const linesFirstPage = Math.max(1, Math.floor((firstTop - margin) / leading));
    const linesNextPage = Math.max(1, Math.floor((PH - margin * 2) / leading));

    let cursor = 0;
    let chunkIndex = 0;
    do {
      const capacity = chunkIndex === 0 ? linesFirstPage : linesNextPage;
      const chunk = lines.slice(cursor, cursor + capacity);
      cursor += capacity;

      let stream = '';
      if (page.title && chunkIndex === 0) {
        const titleY = PH - margin - titleSize;
        stream += `BT /${PDF_FONT.bold} ${titleSize} Tf ${margin} ${titleY.toFixed(2)} Td ` +
          `(${pdfEscape(page.title)}) Tj ET\n`;
        stream += `${margin} ${(titleY - 12).toFixed(2)} m ${(PW - margin).toFixed(2)} ` +
          `${(titleY - 12).toFixed(2)} l 0.7 w 0.8 0.8 0.8 RG S 0 0 0 RG\n`;
      }
      if (page.subtitle && chunkIndex === 0) {
        stream += `BT /${PDF_FONT.regular} 13 Tf 0.35 0.35 0.35 rg ${margin} ` +
          `${(PH - margin - titleSize - 34).toFixed(2)} Td (${pdfEscape(page.subtitle)}) Tj ET 0 0 0 rg\n`;
      }
      if (chunk.length) {
        const startY = (chunkIndex === 0 ? firstTop : PH - margin) -
          (page.subtitle && chunkIndex === 0 ? 26 : 0);
        stream += `BT /${PDF_FONT.regular} ${bodySize} Tf ${leading} TL ` +
          `${margin} ${startY.toFixed(2)} Td\n`;
        for (const line of chunk) stream += `(${pdfEscape(line)}) Tj T*\n`;
        stream += 'ET\n';
      }
      stream += footer(page.footer);
      addPage(stream, null);
      chunkIndex += 1;
    } while (cursor < lines.length);
  }

  if (!pageIds.length) {
    addPage(`BT /${PDF_FONT.regular} 12 Tf 56 780 Td (Empty document) Tj ET\n`, null);
  }

  const info = spec.info || {};
  objects[0] = '<< /Type /Catalog /Pages 2 0 R >>';
  objects[1] = `<< /Type /Pages /Count ${pageIds.length} /Kids [` +
    pageIds.map((id) => `${id} 0 R`).join(' ') + '] >>';
  objects[2] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
  objects[3] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
  objects[4] = '<< /Title (' + pdfEscape(info.title || 'Digital Product') + ')' +
    ' /Author (' + pdfEscape(info.author || 'AI Digital Product Factory') + ')' +
    ' /Subject (' + pdfEscape(info.subject || '') + ')' +
    ' /Keywords (' + pdfEscape(info.keywords || '') + ')' +
    ' /Creator (AI Digital Product Factory) /Producer (n8n) >>';

  // ---- serialise: header, objects, xref table, trailer --------------------
  const chunks = [];
  let offset = 0;
  const write = (value) => {
    const buf = Buffer.isBuffer(value) ? value : Buffer.from(String(value), 'latin1');
    chunks.push(buf);
    offset += buf.length;
  };

  write('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  const offsets = [];
  objects.forEach((obj, index) => {
    offsets[index] = offset;
    write(`${index + 1} 0 obj\n`);
    write(obj);
    write('\nendobj\n');
  });

  const xrefOffset = offset;
  write(`xref\n0 ${objects.length + 1}\n`);
  write('0000000000 65535 f \n');
  for (const o of offsets) write(`${String(o).padStart(10, '0')} 00000 n \n`);
  write(
    `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R /Info 5 0 R >>\n` +
    `startxref\n${xrefOffset}\n%%EOF\n`
  );

  return { buffer: Buffer.concat(chunks), page_count: pageIds.length };
}

// ---------------------------------------------------------------------------
// STEP 4 - build a real PDF with the same writer the product line uses.
// No npm package, no external service: if this node is green, the factory can
// produce sellable files on this machine.
// ---------------------------------------------------------------------------
const ctx = $input.first().json;
const reply = ctx.openai_reply || {};

const envLines = [];
for (const [group, keys] of Object.entries(ctx.env_report)) {
  envLines.push(group);
  for (const entry of keys) {
    envLines.push(`   ${entry.set ? '[OK]  ' : '[--]  '}${entry.key}` +
      (entry.value ? ` = ${entry.value}` : '') +
      (entry.source && entry.source !== 'default' ? `  (from ${entry.source})` : ''));
  }
  envLines.push('');
}

const pages = [
  {
    type: 'text',
    cover: true,
    title: 'Setup test passed',
    subtitle: ctx.product_title,
    lines: [
      '',
      'If you can read this page, the following all work on this machine:',
      '',
      '- n8n executes Code nodes',
      `- configuration resolves (Cloud-compatible): ${ctx.cfg_ready ? 'YES' : 'NO'}`,
      `- OpenAI credential: ${ctx.openai_ok === null ? 'skipped' : (ctx.openai_ok ? 'YES' : 'FAILED')}`,
      '- the PDF engine produces a real file (this document)',
      '',
      reply.tagline ? `OpenAI wrote: "${reply.tagline}"` : '',
      Array.isArray(reply.three_words) ? `Keywords: ${reply.three_words.join(', ')}` : '',
      '',
      `Generated: ${new Date().toISOString()}`,
    ].filter((line) => line !== ''),
    footer: 'AI Digital Product Factory - setup test',
  },
  {
    type: 'text',
    title: 'Environment report',
    lines: envLines,
    footer: 'AI Digital Product Factory - setup test',
  },
  {
    type: 'text',
    title: 'What to do next',
    lines: [
      '1. Add the Postgres credential, then run workflow 06 once.',
      '   Send: {"op":"run_start","run_id":"test-1","status":"running"}',
      '',
      '2. Add the OpenAI credential (if you have not), then run workflow 02.',
      '   Send: {"run_id":"test-2","factory":"printable"}',
      '',
      '3. Run workflow 01 with {"factory":"printable","dry_run":true}.',
      '   Images become 1x1 placeholders, so the rehearsal is nearly free.',
      '',
      '4. Only after all three are green, run a real product.',
      '   {"factory":"resume","dry_run":false} is the cheapest one.',
      '',
      'Etsy and Google Drive are needed only for steps 3 and 4.',
      'Everything before that runs without them.',
    ],
    footer: 'AI Digital Product Factory - setup test',
  },
];

const result = buildPdf({
  width: 595.28,
  height: 841.89,
  pages,
  info: { title: 'ADPF setup test', subject: 'installation check' },
});

const base64 = result.buffer.toString('base64');

return [{
  json: {
    ...ctx,
    pdf_pages: result.page_count,
    pdf_bytes: result.buffer.length,
    pdf_ok: result.buffer.length > 1000
      && result.buffer.slice(0, 5).toString('latin1') === '%PDF-',
  },
  // Attaching it as binary means the file is downloadable straight from the
  // n8n output panel - no database and no Drive needed to see the result.
  binary: {
    data: {
      data: base64,
      mimeType: 'application/pdf',
      fileName: 'adpf-setup-test.pdf',
      fileExtension: 'pdf',
    },
  },
}];

// The verdict, in the shape of a checklist a human can read at a glance.
const ctx = $input.first().json;

const checks = [
  { name: '1. n8n runs Code nodes', ok: true,
    detail: 'this node executed' },
  { name: '2. Configuration resolves', ok: ctx.cfg_ready,
    detail: ctx.cfg_ready
      ? 'ok - settings come from the Factory Config node (works on n8n Cloud)'
      : 'Factory Config did not run before Check Setup' },
  { name: '3. OpenAI credential works',
    ok: ctx.openai_ok === null ? null : ctx.openai_ok,
    detail: ctx.openai_ok === null ? (ctx.skip_reason || 'skipped')
      : (ctx.openai_ok ? `ok, cost about $${ctx.openai_usage.approx_cost_usd}`
                       : ctx.openai_problems.join('; ')) },
  { name: '4. PDF engine works', ok: ctx.pdf_ok,
    detail: ctx.pdf_ok ? `${ctx.pdf_pages} pages, ${ctx.pdf_bytes} bytes`
                       : 'PDF was not produced' },
];

const failed = checks.filter((c) => c.ok === false);
const skipped = checks.filter((c) => c.ok === null);

const missing = [];
for (const [group, keys] of Object.entries(ctx.env_report)) {
  const absent = keys.filter((k) => !k.set).map((k) => k.key);
  if (absent.length) missing.push(`${group}: ${absent.join(', ')}`);
}

return [{
  json: {
    ok: failed.length === 0,
    verdict: failed.length === 0
      ? (skipped.length ? 'PASSED (some checks skipped)' : 'PASSED - n8n is ready')
      : `FAILED - ${failed.length} check(s) need attention`,
    checks,
    failed: failed.map((c) => `${c.name}: ${c.detail}`),
    env_still_missing: missing,
    next_step: failed.length === 0
